  "privacy.breadcrumbLabel": "ಗೌಪ್ಯತೆ ನೀತಿ",
  "privacy.headTitle": "ಗೌಪ್ಯತೆ ನೀತಿ - {appName}",
  "privacy.kicker": "DPDP ಕಾಯಿದೆ 2023 ಶಾಸನಬದ್ಧ ಅನುಸರಣೆ",
  "privacy.title": "ಗೌಪ್ಯತೆ ನೀತಿ",
  "privacy.lastUpdated": "ಕೊನೆಯದಾಗಿ ನವೀಕರಿಸಲಾಗಿದೆ: ಸೆಪ್ಟೆಂಬರ್ 2026 • ಭಾರತ ಸರ್ಕಾರ ರಾಷ್ಟ್ರೀಯ ಡಿಜಿಟಲ್ ಮೂಲಸೌಕರ್ಯ",
  "privacy.section1.heading": "1. ಶಾಸನಬದ್ಧ ಬದ್ಧತೆ ಮತ್ತು ವ್ಯಾಪ್ತಿ",
  "privacy.section2.heading": "2. ನಾವು ಸಂಗ್ರಹಿಸುವ ಡೇಟಾ (ಡೇಟಾ ಮಿನಿಮೈಸೇಶನ್‌ನ ತತ್ವ)",
  "privacy.section3.heading": "3. ಸಂಸ್ಕರಣೆ ಮತ್ತು ನೇರ ಪಾವತಿಗಳ ಉದ್ದೇಶ",
  "privacy.section3.intro": "ಸಂಗ್ರಹಿಸಿದ ಡೇಟಾವನ್ನು ಈ ಕೆಳಗಿನ ಸ್ಪಷ್ಟ ಉದ್ದೇಶಗಳಿಗಾಗಿ ಮಾತ್ರ ಸಂಸ್ಕರಿಸಲಾಗುತ್ತದೆ:",
  "privacy.section3.bullet1": "0% ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಕಡಿತಗಳೊಂದಿಗೆ ಕುಶಲಕರ್ಮಿಗಳ ಸಂಘಗಳಿಗೆ ನೇರ DBT ಬ್ಯಾಂಕ್ ಪಾವತಿಗಳನ್ನು ಸುಗಮಗೊಳಿಸುವುದು.",
  "privacy.section3.bullet2": "ಮಿಂಟಿಂಗ್ ಟ್ಯಾಂಪರ್-ಪ್ರೂಫ್ ಕ್ರಿಪ್ಟೋಗ್ರಾಫಿಕ್ Ed25519 ಡಿಜಿಟಲ್ ಮೂಲ ಪ್ರಮಾಣಪತ್ರಗಳು.",
  "privacy.section3.bullet4": "SMS ಮತ್ತು ಇಮೇಲ್ ಮೂಲಕ ಪೂರೈಸುವಿಕೆ ಮತ್ತು ವಿತರಣಾ ಸ್ಥಿತಿಯ ಅಧಿಸೂಚನೆಗಳನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳುವುದು.",
  "privacy.section4.heading": "4. ಮೂರನೇ ವ್ಯಕ್ತಿಯ ಡೇಟಾ ಮಾರಾಟದ ಮೇಲೆ ಸಂಪೂರ್ಣ ನಿಷೇಧ",
  "privacy.section5.heading": "5. ಕ್ರಿಪ್ಟೋಗ್ರಾಫಿಕ್ ಭದ್ರತೆ ಮತ್ತು ಕುಕಿ ನೀತಿ",
  "privacy.section6.heading": "6. ಡೇಟಾ ವಿಷಯ ಹಕ್ಕುಗಳು ಮತ್ತು ಕುಂದುಕೊರತೆ ಪರಿಹಾರ",
  "terms.breadcrumbLabel": "ಸೇವಾ ನಿಯಮಗಳು",
  "terms.headTitle": "ಸೇವಾ ನಿಯಮಗಳು - {appName}",
  "terms.kicker": "ಸರ್ಕಾರಿ ಆಡಳಿತ ಮತ್ತು ಗಿಲ್ಡ್ ಆದೇಶ",
  "terms.title": "ಸೇವಾ ನಿಯಮಗಳು",
  "terms.lastUpdated": "ಕೊನೆಯದಾಗಿ ನವೀಕರಿಸಲಾಗಿದೆ: ಸೆಪ್ಟೆಂಬರ್ 2026 • ಸಾಮಾಜಿಕ ನ್ಯಾಯ ಮತ್ತು ಸಬಲೀಕರಣ ಸಚಿವಾಲಯ, ಭಾರತ ಸರ್ಕಾರ",
  "terms.section1.heading": "1. ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಆದೇಶ ಮತ್ತು ಸಾರ್ವಜನಿಕ ಮೂಲಸೌಕರ್ಯ",
  "terms.section2.heading": "2. ಭೌಗೋಳಿಕ ಸೂಚನೆಗಳು (GI) ಮತ್ತು ದೃಢೀಕರಣ ಗುಣಮಟ್ಟ",
  "terms.section3.heading": "3. 100% ನೇರ ಪಾವತಿಗಳು ಮತ್ತು 0% ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಕಡಿತಗಳು",
  "terms.section4.heading": "4. ಆದೇಶ ಮತ್ತು ಸಾಂಸ್ಥಿಕ ಪೂರೈಸುವಿಕೆ",
  "terms.section5.heading": "5. ಸಾಂಪ್ರದಾಯಿಕ ಸಾಂಸ್ಕೃತಿಕ ಅಭಿವ್ಯಕ್ತಿಗಳ ಬೌದ್ಧಿಕ ಆಸ್ತಿ",
  "terms.section6.heading": "6. ವಿವಾದ ಪರಿಹಾರ ಮತ್ತು ನ್ಯಾಯವ್ಯಾಪ್ತಿ",
